/* B15m: per-world cover/obstacle storage lives in w->mapgen_state /
 * w->mapgen_state_free (F2k), mirroring csrc/mission.c's om_mis/om_mis_ro
 * (mission_state) convention exactly -- never a file-static registry keyed
 * by om_world* (the ABA hazard csrc/unit.c's own comment documents avoiding).
 * Handles are 1-based row indices (index + 1); 0 stays the "no feature"
 * sentinel used everywhere else in this file's stub family, returned when
 * the fixed-size table is full. Geometry (position, radius, cover height)
 * is recorded verbatim; nothing here decides what "blocking" means for a
 * given height -- that judgment belongs to the module that reads it back
 * (fog.c line-of-sight, tactical_move.c route blocking), same as
 * om_map_sample_obstacle_density below only reports density, not a
 * pass/fail. */
/* A134: one disc per 500 wu patch of the largest canvas, 56 x 56. */
#define OM_MAPGEN_MAX_COVER 3136
#define OM_MAPGEN_MAX_OBSTACLES 3136
/* No header cap exists. Spine is 10 to 30 nodes (R-113, E-17); headroom for spawn points and structures. */
#define OM_MAPGEN_MAX_NODES 128
#define OM_MAPGEN_MAX_STRUCTURES 64
/* E-17 S-113 spine node type list order: objective, staging, transit, chokepoint, flank_route, vantage, hazard_anchor, spawn_point, extraction. */
#define OM_MAPGEN_NODE_SPAWN_POINT 7
/* Returned by the add functions when their table is full, and by the node lookups for "none". */
#define OM_MAPGEN_NO_NODE UINT32_MAX
/* simulation/config.py CANVAS_SIMULATION_MODIFIER_RANGE. Region fields run 0..100 (R-116-02 tests), centred on 50. */
#define OM_MAPGEN_CANVAS_MODIFIER_RANGE 0.30
/* E-10 S-073 archetype indices with a stated canvas direction. */
#define OM_MAPGEN_ARCH_DEFENSIVE_STAND 0
#define OM_MAPGEN_ARCH_SUPPRESSION 4
#define OM_MAPGEN_ARCH_COUNTERINSURGENCY 9
#define OM_MAPGEN_FIELD_MID 50.0
#define OM_MAPGEN_FIELD_MAX 100.0
/* simulation/config.py CANVAS_SMALL / CANVAS_MEDIUM / CANVAS_LARGE; Q-118-01 closed (a): fixed base, +-30 percent by region. No om_constants.h names. */
#define OM_MAPGEN_CANVAS_BASE_SMALL 8000.0
#define OM_MAPGEN_CANVAS_BASE_MEDIUM 16000.0
#define OM_MAPGEN_CANVAS_BASE_LARGE 24000.0

/* Obstacle sample grid: cells at least 200 wu, at most 128 a side; the box is padded 1 wu so a point on a disc edge stays in range. */
#define OM_MAPGEN_OBS_CELL 200.0
#define OM_MAPGEN_OBS_MAX_SIDE 128
#define OM_MAPGEN_OBS_PAD 1.0

/* The 28,000 wu canvas at the 100 wu route cell: 280 cells a side. */
enum { OM_MAPGEN_GRID_SIDE = (int)(OM_MAP_MAX_CANVAS / OM_NAVMESH_CELL_SIZE) };
#define OM_MAPGEN_BITS_PER_BYTE 8
#define OM_MAPGEN_BYTE_SHIFT 3
#define OM_MAPGEN_BIT_MASK 7

typedef struct {
    double x, y, radius, height;
} om_mapgen_cover_row;

typedef struct {
    double x, y, radius;
} om_mapgen_obstacle_row;

typedef struct {
    double  x, y;
    int     type;
    int32_t faction;
} om_mapgen_node_row;

typedef struct {
    double  x, y;
    int32_t owner_faction;
} om_mapgen_structure_row;

typedef struct {
    om_mapgen_cover_row    cover[OM_MAPGEN_MAX_COVER];
    uint32_t               n_cover;
    om_mapgen_obstacle_row obstacles[OM_MAPGEN_MAX_OBSTACLES];
    uint32_t               n_obstacles;
    /* Lazy uniform grid over the obstacle discs for point samples; each cell lists disc indices
     * ascending. Rebuilt on first sample after an add (obs_dirty). */
    int                     obs_dirty;
    int                     obs_side;
    double                  obs_x0, obs_y0, obs_cell;
    uint32_t               *obs_start;
    uint32_t               *obs_ids;
    /* Index-ordered; rows are in insertion order. Spine nodes (faction 0) and spawn points share
     * this table, as spawn_point is a spine node type. Structures have no spine type and are kept
     * apart; the ids the add functions return are 1-based indices into these tables. */
    om_mapgen_node_row      nodes[OM_MAPGEN_MAX_NODES];
    uint32_t                n_nodes;
    om_mapgen_structure_row structures[OM_MAPGEN_MAX_STRUCTURES];
    uint32_t                n_structures;
    int                     has_canvas;
    double                  canvas_w, canvas_h;
    /* A132/A134: route grid, one blocked bit per 100 wu cell per layer, row-major by cy then cx. */
    uint8_t                 blocked_bits[(OM_LAYER_COUNT * OM_MAPGEN_GRID_SIDE * OM_MAPGEN_GRID_SIDE + OM_MAPGEN_BIT_MASK) / OM_MAPGEN_BITS_PER_BYTE];
} om_mapgen_state;

static uint32_t om_mg_net_size(const om_world *w);
static void om_mg_net_write(const om_world *w, uint8_t *out);
static int om_mg_net_read(om_world *w, const uint8_t *buf, uint32_t len);

static void om_mapgen_state_free(void *p) {
    om_mapgen_state *st = (om_mapgen_state *)p;
    if (st) { free(st->obs_start); free(st->obs_ids); }
    free(p);
}

/* Lazily calloc's the per-world mapgen state, mirroring om_mis()/om_tac()
 * exactly. Writes w->mapgen_state -- read-only entry points go through
 * om_mgs_ro() instead, which never allocates (a world with no recorded
 * features yet must not fault on a pure query). */
static om_mapgen_state *om_mgs(om_world *w) {
    om_mapgen_state *st = (om_mapgen_state *)w->mapgen_state;
    if (!st) {
        st = (om_mapgen_state *)calloc(1, sizeof(om_mapgen_state));
        w->mapgen_state = st;
        w->mapgen_state_free = om_mapgen_state_free;
        w->mapgen_state_size = om_mg_net_size;
        w->mapgen_state_write = om_mg_net_write;
        w->mapgen_state_read = om_mg_net_read;
    }
    return st;
}

static const om_mapgen_state *om_mgs_ro(const om_world *w) {
    return (const om_mapgen_state *)w->mapgen_state;
}

/* Feature lookup by handle: 1-based index back to the recorded row, or NULL
 * for an out-of-range or never-allocated handle. Internal only -- no public
 * symbol in ouroboros_sim.h takes a cover/obstacle handle back in, so this
 * stays a private helper for the sample functions below. */
static const om_mapgen_cover_row *om_mgs_cover_at(const om_mapgen_state *st, uint32_t handle) {
    if (!st || handle == 0 || handle > st->n_cover) return NULL;
    return &st->cover[handle - 1];
}

static const om_mapgen_obstacle_row *om_mgs_obstacle_at(const om_mapgen_state *st, uint32_t handle) {
    if (!st || handle == 0 || handle > st->n_obstacles) return NULL;
    return &st->obstacles[handle - 1];
}

/* Squared distance avoids a libm sqrt call entirely: comparing against
 * radius^2 is exact where comparing against radius would need one. */
static double om_mgs_dist_sq(double ax, double ay, double bx, double by) {
    double dx = ax - bx;
    double dy = ay - by;
    return dx * dx + dy * dy;
}

/* Route grid. Cells run 0 .. ceil(canvas / cell) - 1 on each axis; anything outside is blocked. */
static int om_mgs_cells(double extent) {
    int n = (int)(extent / OM_NAVMESH_CELL_SIZE);
    if ((double)n * OM_NAVMESH_CELL_SIZE < extent) n++;
    return n;
}

static size_t om_mgs_bit(uint32_t layer, int cx, int cy) {
    return ((size_t)layer * OM_MAPGEN_GRID_SIDE + (size_t)cy) * OM_MAPGEN_GRID_SIDE + (size_t)cx;
}

static int om_mgs_in_canvas(const om_mapgen_state *st, uint32_t layer, int32_t cx, int32_t cy) {
    return layer < OM_LAYER_COUNT && cx >= 0 && cy >= 0
        && cx < om_mgs_cells(st->canvas_w) && cy < om_mgs_cells(st->canvas_h);
}

static void om_mgs_set_bit(om_mapgen_state *st, uint32_t layer, int cx, int cy, int on) {
    size_t b = om_mgs_bit(layer, cx, cy);
    if (on) st->blocked_bits[b >> OM_MAPGEN_BYTE_SHIFT] = (uint8_t)(st->blocked_bits[b >> OM_MAPGEN_BYTE_SHIFT] | (1u << (b & OM_MAPGEN_BIT_MASK)));
    else st->blocked_bits[b >> OM_MAPGEN_BYTE_SHIFT] = (uint8_t)(st->blocked_bits[b >> OM_MAPGEN_BYTE_SHIFT] & ~(1u << (b & OM_MAPGEN_BIT_MASK)));
}

/* Route-grid read for the other tactical files: 1 blocked, 0 open; outside the canvas blocked; no canvas, 0.
 * Defined here only, not in the header (internal helper). See also: om_map_block_rect. */
int om_mapgen_cell_blocked(const om_world *w, uint32_t layer, int32_t cx, int32_t cy) {
    const om_mapgen_state *st = w ? om_mgs_ro(w) : NULL;
    size_t b;
    if (!st || !st->has_canvas) return 0;
    if (!om_mgs_in_canvas(st, layer, cx, cy)) return 1;
    b = om_mgs_bit(layer, cx, cy);
    return (st->blocked_bits[b >> OM_MAPGEN_BYTE_SHIFT] >> (b & OM_MAPGEN_BIT_MASK)) & 1;
}

/* 1 when no cell can be blocked and no obstacle disc exists: no canvas (so no edge and no route grid) and no
 * obstacle. Lets collision skip its per-push terrain reads. See also: om_move_slide in tactical_move.c. */
int om_mapgen_terrain_free(const om_world *w) {
    const om_mapgen_state *st = w ? om_mgs_ro(w) : NULL;
    return !st || (!st->has_canvas && st->n_obstacles == 0);
}

/* Called by om_map_set_obstacle_density (tactical_move.c): a density above the R-097-01 threshold blocks the
 * cell, anything at or below opens it. Ignored with no canvas or outside it. */
void om_mapgen_cell_set_density(om_world *w, uint32_t layer, int32_t cx, int32_t cy, double density) {
    om_mapgen_state *st = w ? (om_mapgen_state *)w->mapgen_state : NULL;
    if (!st || !st->has_canvas || !om_mgs_in_canvas(st, layer, cx, cy)) return;
    om_mgs_set_bit(st, layer, cx, cy, om_route_grid_is_cell_blocked(density));
}

